"  const scrollToRef = (ref: React.RefObject<HTMLDivElement>, tabName: 'briefing' | 'songs' | 'practice_board' | 'campus_cup') => {
    setActiveTab(tabName);
    onTabChange?.(tabName);
    if (ref.current) {
      ref.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };"

